absolute; //Needed for modal dialog on product-configuration page\n      transition: right 300ms;\n      margin: -1px 0 0 0;\n      right: -20rem;\n      width: 40rem;\n      max-width: 100vw;\n      top: 0;\n      .modal-content {\n        height: 100vh;\n      }\n    }\n  }\n}\n\n.width-fixed {\n  min-width: 8rem;\n  max-width: 8rem;\n}\n\n.option-item {\n  padding-left: 1.5rem;\n}\n\n    \n\n    \n        \n        \n            \n                Legend\n            \n            \n                Html element\n            \n            \n                Component\n            \n            \n                Html element with directive\n            \n        \n    \n\n    \n\n\n\n\n\n\n        var COMPONENT_TEMPLATE = '﻿      @if (product$ | async; as product) {          @if (position === \\'middle\\') {                                  }              @if (position === \\'middle\\') {                  {{\\'COMMON.PRODUCT_CONFIGURATION\\' | translate}}                }        @if (position === \\'middle\\') {                              {{product?.Name}}            @if (product.ProductCode) {                        }                                                              {{\\'COMMON.NET_PRICE\\' | translate}}                                            @if (changes?.length > 0) {                {{cartItem?.NetPrice | localCurrency | async}}                } @else if (relatedTo) {                  {{relatedTo?.NetPrice | localCurrency | async}}                } @else {                                  }                                                    @if (secondaryButton) {                              {{secondaryButton.label | translate}}                            }              @if (actionButton && hideActionBtn) {                              {{actionButton.label                  | translate}}                            }                                      }                @if (position === \\'middle\\') {                    {{product?.Name}}        